function ActivityCakeShopOptionEntryDialog:RefreshBtnUnLockStatus(go,status)
    local unLockRoot = go.transform:Find("RootLock").gameObject
    local lockRoot = go.transform:Find("Root").gameObject
    if not isNull(unLockRoot) then
        KTool.SetActive(unLockRoot.gameObject,not status)
    end

    if not isNull(lockRoot) then
        KTool.SetActive(lockRoot.gameObject, status)
    end
end

