function ActivityCakeShopOptionEntryDialog:Refresh(data)
    self:SetTimeShow()
    self:RefreshRedPoint(data)
    self:RefreshBtnStatus()
    self:PlayBgm(data)
end

function ActivityCakeShopOptionEntryDialog:PlayBgm(data)
    ---@type CriWareUtils
    local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
    CriWareUtils.PlayMusicById(data.scheduleConf.bgm)
end

function ActivityCakeShopOptionEntryDialog:RefreshRedPoint(data)
    CfUtils.SetActive(self.BtnManageRed,data.taskTips == 0)
    CfUtils.SetActive(self.BtnProtectRed,data.bossTips == 0)
    CfUtils.SetActive(self.BtnExchangeRed,data.luckyDrawTips == 0)
end

function ActivityCakeShopOptionEntryDialog:SetTimeShow()
    --region 时间
    local startTime =  self.activityData.startTime
    local closeTime =  self.activityData.closeTime
    local ActivityUtils         = import("Game.Activity.ActivityUtils")
    CfUtils.FillText(self.TextTime, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))
    -- CfUtils.FillText(self.TextTime, os.date("%Y.%m.%d", startTime).."-"..os.date("%Y.%m.%d  %H:%M", closeTime))
end

function ActivityCakeShopOptionEntryDialog:RequestShow()
    GameUtils.Request(Interfaces.OverseaActivityCatParadiseHome,{ activityUuid = self.activityData.id},function(request,response)
        if response.errCode == 0 then
            ActivityCakeUtils.GetActivityCakeMgr():InitialDojo(response.data)
            self:Refresh(response.data)
        end
    end)
end

function ActivityCakeShopOptionEntryDialog:OnBtnExchangeClick()
    local id = self:GetIdByIndex(4)
    local isUnLock = self:IsUnLockFuncById(id)
    if isUnLock then
        CS.Engine.UI.UIModule.OpenDialog({ id = self:GetModuleId(id)},{{id = self.controller.Argument.id }})
    else
        local des = self:GetUnLockDes(id)
        GameUtils.Toast(des)
    end
end

function ActivityCakeShopOptionEntryDialog:IsActivityClose()
    ---@type PlayerComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if not comp then
        return
    end
    local curTime = comp:GetPlayerDojo():GetServerTime()
    curTime = curTime or os.time()
    return curTime > self.activityData.endTime
end

function ActivityCakeShopOptionEntryDialog:OnBtnDrawClick()
    local GachaponUtils = import('Game.Gachapon.GachaponUtils')
    GachaponUtils.OpenGachapon(nil, { { id = self.controller.Argument.id } })
end

function ActivityCakeShopOptionEntryDialog:OnBtnManageClick()
    local isActivityClose = self:IsActivityClose()
    if isActivityClose then
        GameUtils.Toast(localize("活动已经结束"))
        return
    end
    local id = self:GetIdByIndex(5)
    local isUnLock = self:IsUnLockFuncById(id)
    if isUnLock then
        CS.Engine.UI.UIModule.OpenDialog({ id = self:GetModuleId(id)},{{id = self.controller.Argument.id}})
    else
        local des = self:GetUnLockDes(id)
        GameUtils.Toast(des)
    end
end

function ActivityCakeShopOptionEntryDialog:OnBtnMakeClick()
    local isActivityClose = self:IsActivityClose()
