function ActivityCakeShopOptionEntryDialog:IsUnLockFuncById(id)
    local homeDojo = ActivityCakeUtils.GetActivityCakeMgr():GetActivityDojo()
    return homeDojo:IsBtnUnLock(id)
end

function ActivityCakeShopOptionEntryDialog:GetModuleId(id)
    local homeDojo = ActivityCakeUtils.GetActivityCakeMgr():GetActivityDojo()
    return homeDojo:GetModuleId(id)
end

function ActivityCakeShopOptionEntryDialog:GetUnLockDes(id)
    local homeDojo = ActivityCakeUtils.GetActivityCakeMgr():GetActivityDojo()
    local chapterId = homeDojo:GetUnLockChapterId(id)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6240, "ActivityCakeMainLineLevelVo", chapterId)
    if not isNull(vo) then
        return localize("通关故事模式_levelName_后解锁",{_levelName_ = vo.levelName})
    end
    return ""
end

function ActivityCakeShopOptionEntryDialog:GetIdByIndex(index)
    return self.activityData.activityContentId * 100 + index
end

